style.css:
@-moz-document domain("youtube.com") {
/* --- GLOBAL BACKGROUND (Aqua Gradient) --- */
  body, ytd-app, #content, #page-manager {
    background: linear-gradient(135deg, #0ad1ff, #19ffa5) !important;
    color: #003c47 !important;
  }

  /* --- TOP BAR --- */
  ytd-masthead {
    background: linear-gradient(90deg, #00c4ff, #00ffcf) !important;
    border-bottom: 2px solid #00ffe2 !important;
  }

  /* --- SEARCH BAR --- */
  #search-input input {
    background: rgba(255, 255, 255, 0.4) !important;
    backdrop-filter: blur(6px);
    border: 2px solid rgba(255,255,255,0.7) !important;
    border-radius: 20px !important;
    color: #004c4c !important;
  }

  #search-icon-legacy {
    background: linear-gradient(135deg, #00eaff, #00ffbf) !important;
    border-radius: 20px !important;
  }

  /* --- SIDEBAR --- */
  ytd-guide-renderer {
    background: rgba(255, 255, 255, 0.25) !important;
    backdrop-filter: blur(7px);
  }

  ytd-guide-entry-renderer:hover {
    background: rgba(255, 255, 255, 0.4) !important;
  }

  /* --- VIDEO TITLES --- */
  #video-title {
    color: #004f5a !important;
    text-shadow: 0 1px 2px rgba(255,255,255,0.8);
  }

  /* --- LINKS / TEXT --- */
  a, .yt-simple-endpoint, yt-formatted-string {
    color: #005b73 !important;
  }

  /* --- SUBSCRIBE BUTTON (aqua gel style) --- */
  ytd-subscribe-button-renderer button {
    background: linear-gradient(145deg, #00e1ff, #00ffb3) !important;
    border: 2px solid rgba(255,255,255,0.8) !important;
    border-radius: 20px !important;
    color: #003531 !important;
    box-shadow: 0 3px 8px rgba(0,0,0,0.2);
  }

  ytd-subscribe-button-renderer button:hover {
    background: linear-gradient(145deg, #00c3e6, #00e89b) !important;
  }

  /* --- ACTION BUTTONS --- */
  ytd-toggle-button-renderer button {
    background: rgba(255,255,255,0.35) !important;
    border: 1px solid rgba(255,255,255,0.7) !important;
    border-radius: 12px !important;
  }
  ytd-toggle-button-renderer button:hover {
    background: rgba(255,255,255,0.5) !important;
  }

  /* --- COMMENTS --- */
  #comments {
    background: rgba(255,255,255,0.22) !important;
    backdrop-filter: blur(6px);
    border-radius: 18px;
  }
  #content-text {
    color: #003d44 !important;
  }

  /* --- BUBBLES EFFECT --- */
  body::after {
    content: "";
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    pointer-events: none;
    z-index: 999999;

    background-image:
      radial-gradient(circle, rgba(255,255,255,0.6) 6px, transparent 7px),
      radial-gradient(circle, rgba(255,255,255,0.4) 4px, transparent 6px),
      radial-gradient(circle, rgba(255,255,255,0.7) 3px, transparent 5px);

    background-size: 180px 180px, 240px 240px, 130px 130px;
    animation: bubblesFloat 18s linear infinite;
  }

  @keyframes bubblesFloat {
    0%   { background-position: 0 100%, 50px 120%, -30px 90%; }
    100% { background-position: 0 -200%, 50px -180%, -30px -150%; }
  }

  /* --- SCROLLBAR --- */
  ::-webkit-scrollbar {
    width: 10px;
  }
  ::-webkit-scrollbar-thumb {
    background: linear-gradient(180deg, #00e1ff, #00ffb3) !important;
    border-radius: 8px;
  }
  ::-webkit-scrollbar-track {
    background: rgba(255,255,255,0.25) !important;
  }
}
